function currentWallet(PDO $pdo,int $uid,bool $lock=false): WalletUser {
 $sql="SELECT u.*,w.id wallet_id,w.balance,w.wallet_status,w.pin,w.updated_at FROM users u JOIN wallets w ON w.user_id=u.id WHERE u.id=?".($lock?' FOR UPDATE':'');
 $st=$pdo->prepare($sql);$st->execute([$uid]);$row=$st->fetch();if(!$row)throw new RuntimeException('Akun tidak ditemukan.');return new WalletUser($row);
}
function recordTx(PDO $pdo,int $uid,string $type,float $amount,string $desc):void{$st=$pdo->prepare("INSERT INTO transactions(user_id,type,amount,description,reference_code) VALUES(?,?,?,?,?)");$st->execute([$uid,$type,$amount,$desc,'KNY'.strtoupper(bin2hex(random_bytes(4)))]);}
function adminOnly(PDO $pdo,int $uid):void{$s=$pdo->prepare("SELECT role FROM users WHERE id=?");$s->execute([$uid]);if($s->fetchColumn()!=='admin')throw new RuntimeException('Akses khusus admin toko.');}
function cartData(PDO $pdo,int $uid):array{$s=$pdo->prepare("SELECT c.id cart_id,c.quantity,c.variant,p.id product_id,p.name,p.price,p.stock,p.image_url,p.weight FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=? ORDER BY c.id DESC");$s->execute([$uid]);return $s->fetchAll();}
