 if($action==='product_detail'){$s=$pdo->prepare("SELECT p.*,COALESCE(AVG(r.rating),p.rating) avg_rating,COUNT(r.id) review_count FROM products p LEFT JOIN reviews r ON r.product_id=p.id WHERE p.id=? GROUP BY p.id");$s->execute([(int)$data['id']]);$product=$s->fetch();if(!$product)throw new RuntimeException('Produk tidak ditemukan.');$r=$pdo->prepare("SELECT r.rating,r.comment,r.photo_url,r.created_at,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.id DESC LIMIT 10");$r->execute([$product['id']]);jsonResponse(['ok'=>true,'product'=>$product,'reviews'=>$r->fetchAll()]);}
