  $aid=(int)($data['address_id']??0);$ad=$pdo->prepare("SELECT * FROM addresses WHERE id=? AND user_id=?");$ad->execute([$aid,$uid]);if(!$ad->fetch())throw new RuntimeException('Pilih alamat pengiriman yang valid.');$courier=$data['courier']??'KOINY Express';$shipping=max(9000,(int)ceil($weight/1000)*12000);if($courier==='Reguler')$shipping+=2000;if($courier==='Kilat')$shipping+=10000;
