  $track='KNY'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare("INSERT INTO orders(user_id,address_id,subtotal,shipping_cost,discount,total,courier,payment_method,payment_status,order_status,voucher_code,tracking_number) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$uid,$aid,$subtotal,$shipping,$discount,$total,$courier,$method,$status,'processing',$voucher?:null,$track]);$oid=(int)$pdo->lastInsertId();
  foreach($items as $it){$ins=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,variant,price,quantity) VALUES(?,?,?,?,?,?)");$ins->execute([$oid,$it['product_id'],$it['name'],$it['variant'],$it['price'],$it['quantity']]);$stock=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");$stock->execute([$it['quantity'],$it['product_id'],$it['quantity']]);if(!$stock->rowCount())throw new RuntimeException('Stok berubah. Silakan ulangi checkout.');}
  $d=$pdo->prepare("DELETE FROM cart_items WHERE user_id=?");$d->execute([$uid]);$pdo->commit();jsonResponse(['ok'=>true,'message'=>'Pesanan berhasil dibuat.','order_id'=>$oid,'tracking_number'=>$track,'total'=>$total,'payment_status'=>$status]);
 }
